```json
{
  "root_causes": [
    {
      "service": "recommendation",
      "fault_kind": "pod_unavailable",
      "evidence": [
        {
          "kind": "metric",
          "sql": "SELECT metric, service_name, min(time) t0, max(time) t1, count(*) n, max(value) mx FROM abnormal_metrics WHERE service_name='recommendation' AND metric='k8s.deployment.available' GROUP BY ALL",
          "claim": "recommendation deployment reports available pods only in the normal window; in abnormal it is 0 from about 10:15:55 to the end"
        },
        {
          "kind": "trace",
          "sql": "SELECT service_name, count(*) n, min(time) first_seen, max(time) last_seen FROM abnormal_traces WHERE service_name='recommendation' GROUP BY ALL",
          "claim": "recommendation emits no spans at all during the abnormal window; in normal it emitted 587 spans"
        },
        {
          "kind": "metric",
          "sql": "SELECT service_name, metric, count(*) n, min(time) t0, max(time) t1 FROM abnormal_metrics WHERE service_name='recommendation' GROUP BY ALL",
          "claim": "recommendation's container and pod metrics are absent in the abnormal window"
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "recommendation",
      "to": "frontend",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT span_name, attr_status_code, attr_http_response_status_code, count(*) n, avg(duration)/1e6 avg_ms FROM abnormal_traces WHERE service_name='frontend' AND (span_name LIKE '%GetRecommendations' OR span_name LIKE 'HTTP /recommendations') GROUP BY ALL",
          "claim": "frontend's calls to recommendation fail (581 Error spans, about 0.01 ms) and its /recommendations HTTP requests return 500"
        }
      ]
    }
  ]
}
```

